					<?xml version="1.0" encoding="UTF-8"?>
					<feed xmlns="http://www.w3.org/2005/Atom">
						<title>Test Feed</title>
						<icon>https://www.example.com/favicon.ico</icon>
					</feed>""".replace("\n", "\r\n");
		}
	}

